\begin{tikzpicture}[x=1cm,y=1cm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black},line width=0.8pt]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (0,0) rectangle (17,12.4);
\draw[black,rounded corners=3mm] (0.1,0.1) rectangle (16.9,12.3);
\node[font=\fontsize{10}{12}\selectfont\bfseries] at (8.5,11.85) {Real numbers};
\node[align=center,text width=15.6cm] at (8.5,11.1) {All numbers we have been working with so far are collectively called real numbers.};
\draw[black,rounded corners=2mm] (0.5,5.1) rectangle (16.5,10.4);
\node[anchor=north west,font=\fontsize{10}{12}\selectfont\bfseries] at (0.85,10.1) {Rational numbers};
\node[anchor=north west,align=left,text width=5.8cm] at (0.85,9.3) {A number that can be written as $\dfrac{a}{b}$ where $a$ and $b$ are integers and $b\ne0$.};
\node[anchor=north west,align=left,text width=5.8cm] at (0.85,7.65) {$-\dfrac{12}{5}\quad68\%\quad0.42$\\[5mm]$\dfrac{8}{3}\quad0.\dot{3}\quad4\dfrac{2}{5}$};
\draw[black,rounded corners=2mm] (7.1,5.6) rectangle (16.5,10.4);
\node[anchor=north west,font=\fontsize{10}{12}\selectfont\bfseries] at (7.4,10.1) {Integers};
\node[anchor=north west,align=left,text width=3.1cm] at (7.4,9.35) {Whole numbers, including negative numbers.};
\node[anchor=north west] at (7.4,7.6) {$-2\qquad-183$};
\draw[black,rounded corners=2mm] (11.1,6.9) rectangle (16.5,10.4);
\node[font=\fontsize{10}{12}\selectfont\bfseries] at (13.8,9.95) {Natural numbers};
\node[align=center,text width=4.8cm] at (13.8,9.3) {Positive whole numbers};
\node[align=center,text width=4.8cm] at (13.8,8.55) {$1\quad2\quad3\quad62\quad2719$};
\node[align=center,text width=4.8cm] at (13.8,7.55) {$\sqrt{9}\qquad\dfrac{18}{3}\qquad8$};
\draw[black,rounded corners=2mm] (0.5,0.55) rectangle (16.5,4.5);
\node[font=\fontsize{10}{12}\selectfont\bfseries] at (8.5,4.1) {Irrational numbers};
\node[align=center,text width=15cm] at (8.5,3.1) {Irrational numbers cannot be written as $\dfrac{a}{b}$ where $a$ and $b$ are integers and $b\ne0$.\\As decimals, they are non-terminating and non-recurring.\\They go on forever with no repeating pattern.};
\node[align=center,text width=15cm] at (8.5,1.45) {$\pi\approx3.141592\ldots\qquad\sqrt{2}\approx1.4142135\ldots$\\[3mm]$\sqrt{3}\approx1.7320508\ldots\qquad e\approx2.718281\ldots$};
\end{tikzpicture}

